using System;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using CashflowChains.City;
using CashflowChains.Economy;
using CashflowChains.Empire;
public sealed class PermanentCityTests {
 BalanceConfig c;
 [SetUp]public void Setup(){c=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-v1.json")));c.Validate();}
 EmpireEngine New(Func<EmpireAccount,bool> save=null)=>new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="permanent-city-test"}},save??(_=>true));
 EmpireEngine Open(){var e=New();e.OpenCity(100);e.BuildCity("first-cafe","cafe",2,1,101);e.FinishCityBuild("first-cafe",104);return e;}
 [Test]public void FoundingAllocationAndConstructionAreRealIdempotentLedgerCommands(){var e=New();e.OpenCity(100);e.OpenCity(101);Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(6,e.Snapshot.Economy.Amount("BEANS"));e.BuildCity("first-cafe","cafe",2,1,102);Assert.AreEqual(100,e.Snapshot.Economy.Amount("CASH"));Assert.Throws<InvalidOperationException>(()=>e.FinishCityBuild("first-cafe",104));e.FinishCityBuild("first-cafe",105);e.FinishCityBuild("first-cafe",106);Assert.AreEqual(2,e.Snapshot.City.Properties.Count);Assert.AreEqual(1,e.Snapshot.City.Properties.Last().Level);}
 [Test]public void OneCityKeepsItsLayoutsAndFundsWhileDaysAdvanceWithoutASkip(){var e=Open();e.StartCityDay(105);var before=e.Snapshot;Assert.Throws<InvalidOperationException>(()=>e.SettleCityDay(1,109));Assert.AreEqual(before.Economy.Revision,e.Snapshot.Economy.Revision);var report=e.CurrentCityDay();e.SettleCityDay(1,110);var after=e.Snapshot;Assert.AreEqual(before.Economy.Amount("CASH")+report.Net,after.Economy.Amount("CASH"));Assert.AreEqual(2,after.City.Day);Assert.AreEqual(before.City.Properties.Select(p=>p.Id+":"+p.X+":"+p.Y),after.City.Properties.Select(p=>p.Id+":"+p.X+":"+p.Y));e.SettleCityDay(1,111);Assert.AreEqual(after.Economy.Amount("CASH"),e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void ResidentsHaveFiniteDailyCoffeeNeedsAndSalesUseActualBeansAndCups(){var e=Open();var r=e.ForecastCity();Assert.AreEqual(12,r.Population);Assert.AreEqual(6,r.CoffeeDemand);Assert.Greater(r.CoffeeServed,0);Assert.LessOrEqual(r.CoffeeServed,6);Assert.AreEqual(r.CoffeeServed,r.Resources.Single(i=>i.ItemId=="BEANS").Consumed);Assert.AreEqual(r.CoffeeServed,r.Resources.Single(i=>i.ItemId=="CUPS").Consumed);Assert.Greater(r.Bills,0);Assert.Greater(r.Tax,0);Assert.AreEqual(r.Revenue-r.Bills-r.ImportBills-r.Tax,r.Net);Assert.True(r.Flows.Any(f=>f.Kind=="COFFEE"));Assert.True(r.Flows.Any(f=>f.Kind=="CASH"));}
 [Test]public void ChangesDuringTradeApplyToNextDayAndCannotRewriteTheCommittedPlan(){var e=Open();e.StartCityDay(105);var r=e.CurrentCityDay();e.SetCityPrice("premium",2,12500,106);e.MoveCityProperty("move",2,3,3,107);Assert.AreEqual(r.Net,e.CurrentCityDay().Net);Assert.AreEqual(10000,e.Snapshot.City.Trading.Properties.Single(p=>p.Id==2).PriceBasisPoints);Assert.AreEqual(12500,e.Snapshot.City.Properties.Single(p=>p.Id==2).PriceBasisPoints);e.SettleCityDay(1,110);e.StartCityDay(111);Assert.AreEqual(12500,e.Snapshot.City.Trading.Properties.Single(p=>p.Id==2).PriceBasisPoints);}
 [Test]public void TamperedTradingPlansAndConstructionTimersAreRejected(){var e=Open();e.StartCityDay(105);var bad=e.Snapshot;bad.City.Trading.Properties[0].Level=5;Assert.Throws<ArgumentException>(()=>bad.Validate(c));var waiting=New();waiting.OpenCity(100);waiting.BuildCity("build","cafe",2,1,101);bad=waiting.Snapshot;bad.City.Jobs[0].FinishAt--;Assert.Throws<ArgumentException>(()=>bad.Validate(c));}
 [Test]public void ConstructionCapacityAndLandBoundariesAreConcreteConstraints(){var e=Open();e.BuildCity("house","home",0,1,105);Assert.Throws<InvalidOperationException>(()=>e.BuildCity("second","home",0,2,106));Assert.Throws<InvalidOperationException>(()=>e.MoveCityProperty("outside",1,4,4,107));Assert.Throws<InvalidOperationException>(()=>e.BuildCity("occupied","home",1,1,108));}
 [Test]public void FailedPersistenceRollsBackCityProjectionAndMoneyTogether(){bool fail=false;var e=New(_=>!fail);e.OpenCity(100);fail=true;Assert.Throws<InvalidOperationException>(()=>e.BuildCity("cafe","cafe",2,1,101));Assert.AreEqual(200,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(1,e.Snapshot.City.Properties.Count);}
 [Test]public void SeasonsUtilitiesTourismAndTradePreserveAllResources(){var e=Open();for(int day=1;day<=28;day++){var plan=new CityOperatingPlan{Day=day,StartAt=100,FinishAt=200,CashAvailable=10000,Properties=new[]{new CityProperty{Id=1,Kind="home",Level=5},new CityProperty{Id=2,Kind="cafe",Level=2,X=1},new CityProperty{Id=3,Kind="farm",Level=2,Y=1},new CityProperty{Id=4,Kind="warehouse",Level=1,X=2},new CityProperty{Id=5,Kind="grocer",Level=1,Y=2},new CityProperty{Id=6,Kind="port",Level=1,X=3},new CityProperty{Id=7,Kind="hotel",Level=1,Y=3}},Inventory=new ItemAmount[0]};var r=CityDayModel.Forecast(c.City,plan);Assert.AreEqual(new[]{"SPRING","SUMMER","AUTUMN","WINTER"}[(day-1)/7],r.Season);Assert.LessOrEqual(r.CoffeeServed,r.CoffeeDemand);Assert.LessOrEqual(r.Visitors,12);foreach(var i in r.Resources)Assert.AreEqual(i.Initial+i.Produced+i.Imported,i.Consumed+i.Exported+i.Spilled+i.Closing);}}
 [Test]public void SerializedCityPreservesNameLayoutPriceAndPendingDay(){var e=Open();e.RenameCity("name","Riverbank",105);e.StartCityDay(106);var serialized=JsonUtility.ToJson(e.Snapshot);var restored=JsonUtility.FromJson<EmpireAccount>(serialized);restored.Validate(c);var copy=new EmpireEngine(c,restored,_=>true);Assert.AreEqual("Riverbank",copy.Snapshot.City.Name);Assert.AreEqual(e.CurrentCityDay().Net,copy.CurrentCityDay().Net);}
}
